11	/// A service for creating and parsing [Depfile]s.
12	class DepfileService {
13	  DepfileService({
14	    @required Logger logger,
15	    @required FileSystem fileSystem,
16	    @required Platform platform,
17	  }) : _logger = logger,
18	       _fileSystem = fileSystem,
19	       _platform = platform;
20	
21	  final Logger _logger;
22	  final FileSystem _fileSystem;
23	  final Platform _platform;
24	  static final RegExp _separatorExpr = RegExp(r'([^\\]) ');
25	  static final RegExp _escapeExpr = RegExp(r'\\(.)');
26	
27	  /// Given an [depfile] File, write the depfile contents.
28	  ///
29	  /// If either [inputs] or [outputs] is empty, ensures the file does not
30	  /// exist.
31	  void writeToFile(Depfile depfile, File output) {
32	    if (depfile.inputs.isEmpty || depfile.outputs.isEmpty) {
33	      if (output.existsSync()) {
34	        output.deleteSync();
35	      }
36	      return;
37	    }
38	    final StringBuffer buffer = StringBuffer();
39	    _writeFilesToBuffer(depfile.outputs, buffer);
40	    buffer.write(': ');
41	    _writeFilesToBuffer(depfile.inputs, buffer);
42	    output.writeAsStringSync(buffer.toString());
43	  }
44	
45	  /// Parse the depfile contents from [file].
46	  ///
47	  /// If the syntax is invalid, returns an empty [Depfile].
48	  Depfile parse(File file) {
49	    final String contents = file.readAsStringSync();
50	    final List<String> colonSeparated = contents.split(': ');
51	    if (colonSeparated.length != 2) {
52	      _logger.printError('Invalid depfile: ${file.path}');
53	      return const Depfile(<File>[], <File>[]);
54	    }
55	    final List<File> inputs = _processList(colonSeparated[1].trim());
56	    final List<File> outputs = _processList(colonSeparated[0].trim());
57	    return Depfile(inputs, outputs);
58	  }
59	
60	
61	  /// Parse the output of dart2js's used dependencies.
62	  ///
63	  /// The [file] contains a list of newline separated file URIs. The output
64	  /// file must be manually specified.
65	  Depfile parseDart2js(File file, File output) {
66	    final List<File> inputs = <File>[];
67	    for (final String rawUri in file.readAsLinesSync()) {
68	      if (rawUri.trim().isEmpty) {
69	        continue;
70	      }
71	      final Uri fileUri = Uri.tryParse(rawUri);
72	      if (fileUri == null) {
73	        continue;
74	      }
75	      if (fileUri.scheme != 'file') {
76	        continue;
77	      }
78	      inputs.add(_fileSystem.file(fileUri));
79	    }
80	    return Depfile(inputs, <File>[output]);
81	  }
82	
83	  void _writeFilesToBuffer(List<File> files, StringBuffer buffer) {
84	    for (final File outputFile in files) {
85	      if (_platform.isWindows) {
86	        // Foward slashes and spaces in a depfile have to be escaped on windows.
87	        final String path = outputFile.path
88	          .replaceAll(r'\', r'\\')
89	          .replaceAll(r' ', r'\ ');
90	        buffer.write(' $path');
91	      } else {
92	        final String path = outputFile.path
93	          .replaceAll(r' ', r'\ ');
94	        buffer.write(' $path');
95	      }
96	    }
97	  }
98	
99	  List<File> _processList(String rawText) {
100	    return rawText
101	    // Put every file on right-hand side on the separate line
102	        .replaceAllMapped(_separatorExpr, (Match match) => '${match.group(1)}\n')
103	        .split('\n')
104	    // Expand escape sequences, so that '\ ', for example,ß becomes ' '
105	        .map<String>((String path) => path.replaceAllMapped(_escapeExpr, (Match match) => match.group(1)).trim())
106	        .where((String path) => path.isNotEmpty)
107	    // The tool doesn't write duplicates to these lists. This call is an attempt to
108	    // be resillient to the outputs of other tools which write or user edits to depfiles.
109	        .toSet()
110	        .map(_fileSystem.file)
111	        .toList();
112	  }
113	}
114	
115	/// A class for representing depfile formats.
116	class Depfile {
117	  /// Create a [Depfile] from a list of [input] files and [output] files.
118	  const Depfile(this.inputs, this.outputs);
119	
120	  /// The input files for this depfile.
121	  final List<File> inputs;
122	
123	  /// The output files for this depfile.
124	  final List<File> outputs;
125	}
