41	    // This path needs to match the prefix in the rule below.
42	    final String basePath = environment.artifacts
43	      .getArtifactPath(Artifact.windowsDesktopPath);
44	    for (final File input in environment.fileSystem.directory(basePath)
45	        .listSync(recursive: true)
46	        .whereType<File>()) {
47	      final String outputPath = environment.fileSystem.path.join(
48	        environment.projectDir.path,
49	        'windows',
50	        'flutter',
51	        environment.fileSystem.path
52	          .relative(input.path, from: basePath),
