20	/// Copy the macOS framework to the correct copy dir by invoking 'cp -R'.
21	///
22	/// This class is abstract to share logic between the three concrete
23	/// implementations. The shelling out is done to avoid complications with
24	/// preserving special files (e.g., symbolic links) in the framework structure.
25	///
26	/// Removes any previous version of the framework that already exists in the
27	/// target directory.
28	///
29	/// The real implementations are:
30	///   * [DebugUnpackMacOS]
31	///   * [ProfileUnpackMacOS]
32	///   * [ReleaseUnpackMacOS]
33	abstract class UnpackMacOS extends Target {
34	  const UnpackMacOS();
35	
36	  @override
37	  List<Source> get inputs => const <Source>[
38	    Source.pattern('{FLUTTER_ROOT}/packages/flutter_tools/lib/src/build_system/targets/macos.dart'),
39	  ];
40	
41	  @override
42	  List<Source> get outputs => const <Source>[];
43	
44	  @override
45	  List<Target> get dependencies => <Target>[];
46	
47	  @override
48	  List<String> get depfiles => const <String>['unpack_macos.d'];
49	
50	  @override
51	  Future<void> build(Environment environment) async {
52	    if (environment.defines[kBuildMode] == null) {
53	      throw MissingDefineException(kBuildMode, 'unpack_macos');
54	    }
55	    final BuildMode buildMode = getBuildModeForName(environment.defines[kBuildMode]);
56	    final String basePath = globals.artifacts.getArtifactPath(Artifact.flutterMacOSFramework, mode: buildMode);
57	    final Directory targetDirectory = environment
58	      .outputDir
59	      .childDirectory('FlutterMacOS.framework');
60	    // Deleting this directory is required or else the FlutterMacOS module
61	    // cannot be found.
62	    if (targetDirectory.existsSync()) {
63	      targetDirectory.deleteSync(recursive: true);
64	    }
65	    final List<File> inputs = globals.fs.directory(basePath)
66	      .listSync(recursive: true)
67	      .whereType<File>()
68	      .toList();
69	    final List<File> outputs = inputs.map((File file) {
70	      final String relativePath = globals.fs.path.relative(file.path, from: basePath);
71	      return globals.fs.file(globals.fs.path.join(targetDirectory.path, relativePath));
72	    }).toList();
73	    final ProcessResult result = await globals.processManager
74	        .run(<String>['cp', '-R', basePath, targetDirectory.path]);
75	    if (result.exitCode != 0) {
76	      throw Exception(
77	        'Failed to copy framework (exit ${result.exitCode}:\n'
78	        '${result.stdout}\n---\n${result.stderr}',
79	      );
80	    }
81	    final DepfileService depfileService = DepfileService(
82	      logger: globals.logger,
83	      fileSystem: globals.fs,
84	      platform: globals.platform,
85	    );
86	    depfileService.writeToFile(
87	      Depfile(inputs, outputs),
88	      environment.buildDir.childFile('unpack_macos.d'),
89	    );
90	  }
91	}
