27	/// Copies the Linux desktop embedding files to the copy directory.
28	class UnpackLinuxDebug extends Target {
29	  const UnpackLinuxDebug();
30	
31	  @override
32	  String get name => 'unpack_linux_debug';
33	
34	  @override
35	  List<Source> get inputs => const <Source>[
36	    Source.pattern('{FLUTTER_ROOT}/packages/flutter_tools/lib/src/build_system/targets/linux.dart'),
37	  ];
38	
39	  @override
40	  List<Source> get outputs => const <Source>[];
41	
42	  @override
43	  List<String> get depfiles => <String>[
44	    'linux_engine_sources.d'
45	  ];
46	
47	  @override
48	  List<Target> get dependencies => <Target>[];
49	
50	  @override
51	  Future<void> build(Environment environment) async {
52	    final String basePath = globals.artifacts.getArtifactPath(Artifact.linuxDesktopPath);
53	    final List<File> inputs = <File>[];
54	    final List<File> outputs = <File>[];
55	    final String outputPrefix = globals.fs.path.join(
56	      environment.projectDir.path,
57	      'linux',
58	      'flutter',
59	      'ephemeral',
60	    );
61	    // The native linux artifacts are composed of 6 files and a directory (listed above)
62	    // which need to be copied to the target directory.
63	    for (final String artifact in _kLinuxArtifacts) {
64	      final String entityPath = globals.fs.path.join(basePath, artifact);
65	      // If this artifact is a file, just copy the source over.
66	      if (globals.fs.isFileSync(entityPath)) {
67	        final String outputPath = globals.fs.path.join(
68	          outputPrefix,
69	          globals.fs.path.relative(entityPath, from: basePath),
70	        );
71	        final File destinationFile = globals.fs.file(outputPath);
72	        if (!destinationFile.parent.existsSync()) {
