/// Copies the desktop artifacts from [artifactPath] to the [outputDirectory].
///
/// Only files/directories listed in [artifacts] are copied. If an artifact is
/// a directory, all of its contents are copied recursively.
///
/// Returns a [Depfile] containing all of the inputs and outputs that were
/// copied so that the calling target can track its dependencies.
///
/// Throws an [Exception] if any of the [artifacts] do not exist under
/// [artifactPath].
Depfile unpackDesktopArtifacts({
  @required FileSystem fileSystem,
  @required String artifactPath,
  @required Directory outputDirectory,
  @required List<String> artifacts,
}) {
  final List<File> inputs = <File>[];
  final List<File> outputs = <File>[];
  for (final String artifact in artifacts) {
    final String entityPath = fileSystem.path.join(artifactPath, artifact);
    // If this artifact is a file, just copy the source over.
    if (fileSystem.isFileSync(entityPath)) {
      final String outputPath = fileSystem.path.join(
        outputDirectory.path,
        fileSystem.path.relative(entityPath, from: artifactPath),
      );
      final File destinationFile = fileSystem.file(outputPath);
      if (!destinationFile.parent.existsSync()) {
        destinationFile.parent.createSync(recursive: true);
      }
      final File inputFile = fileSystem.file(entityPath);
      inputFile.copySync(destinationFile.path);
      inputs.add(inputFile);
      outputs.add(destinationFile);
      continue;
    }
    final String directoryPath = fileSystem.path.join(artifactPath, artifact);
    // If the artifact doesn't exist as either a file or directory, throw.
    if (!fileSystem.isDirectorySync(directoryPath)) {
      throw Exception('Failed to copy $artifact');
    }
    // If the artifact is a directory, recursively copy every file from it.
    for (final File input in fileSystem.directory(directoryPath)
        .listSync(recursive: true)
        .whereType<File>()) {
      final String outputPath = fileSystem.path.join(
        outputDirectory.path,
        fileSystem.path.relative(input.path, from: artifactPath),
      );
      final File destinationFile = fileSystem.file(outputPath);
      if (!destinationFile.parent.existsSync()) {
        destinationFile.parent.createSync(recursive: true);
      }
      final File inputFile = fileSystem.file(input);
      inputFile.copySync(destinationFile.path);
      inputs.add(inputFile);
      outputs.add(destinationFile);
    }
  }
  return Depfile(inputs, outputs);
}
